// ToggleGroup — Adw.ToggleGroup
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles toggle-group with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface ToggleGroupProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** guint, from Adw.ToggleGroup */
  active?: number

  /** utf8, from Adw.ToggleGroup */
  activeName?: string

  /** gboolean, from Adw.ToggleGroup */
  canShrink?: boolean

  /** gboolean, from Adw.ToggleGroup */
  homogeneous?: boolean
}

export function ToggleGroup({ className, children }: ToggleGroupProps) {
  return (
    <div className={cn("p-[var(---group-padding)]", "bg-[color-mix(in_srgb,currentColor_10%,transparent)]", "rounded-[9px]", className)}>
      {children}
    </div>
  )
}
